    if (UNLIKELY(!grow_buffer_if_needed(s1, s1->used + sz + 2)))
        return false;

    memcpy(s1->value.buffer + s1->used, s2, sz);
    s1->used += sz;
    s1->value.buffer[s1->used] = '\0';

    return true;
